import {AGENTS} from './data.js';
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const aiStories={
 jordan:{title:'Plan a safer identity handover',benefit:'Help the operator compare Jordan’s records and assemble a conversion plan with explicit prerequisites.',input:'Workforce and contractor records, effective dates, application assignments, claims and workflow history.',output:'A proposed handover checklist: identity matches to verify, access to preserve, overlap to resolve and exceptions requiring an owner.',decision:'An authorized operator confirms the identity match and approves any conversion or access change.',moments:['Compare Jordan’s records and highlight uncertain matches.','Draft the handover sequence and identify unmet prerequisites.','Explain the differences between property roles and package policies.','Summarize first-sign-in readiness and missing assignments.']},
 sofia:{title:'Spot first-day readiness gaps',benefit:'Help the onboarding team see what is ready before Sofia arrives and what still needs attention.',input:'Hire attributes, pre-hire task results, device status, application assignments and authentication-method eligibility.',output:'A readiness summary grouped into ready, needs attention and not yet verified, with a suggested owner for each gap.',decision:'The onboarding owner verifies the findings; an authorized administrator handles assignments or authentication changes.',moments:['Find missing hire attributes and failed preparation tasks.','Summarize device enrollment, policy and compliance gaps.','Suggest role-appropriate access for human review.','Explain a supported bootstrap and registration path.']},
 nadia:{title:'Guide remote onboarding',benefit:'Help support connect Nadia’s device, external authentication and time-bound access into one troubleshooting plan.',input:'Autopilot targeting, device readiness, external-method scope, sign-in evidence, contract dates and package policies.',output:'An ordered troubleshooting checklist with evidence to inspect and a clear distinction between configuration and tested outcomes.',decision:'Support verifies each diagnosis; identity owners approve access and expiry changes.',moments:['Identify missing prerequisites for remote device setup.','Explain why the external authentication method may not appear.','Flag differences between contract dates and access expiry.','Prepare an end-of-contract verification checklist.']},
 sam:{title:'Explain friction across the shift',benefit:'Help the operator understand Sam’s sign-in journey and compare potential kiosk policy changes.',input:'Federation configuration, kiosk mode, Conditional Access settings, report-only results and observed sign-in events.',output:'A policy explanation and proposed troubleshooting steps. Any reduction in prompts remains a hypothesis until tested.',decision:'The policy owner approves enforcement changes; the scoped support operator handles recovery.',moments:['Explain where federation redirects Sam and where it fails.','Compare report-only policy results with actual prompts.','Prepare a scoped recovery checklist with operator verification.','List the evidence needed to prove a clean kiosk handover.']},
 tom:{title:'Turn stale access into a review decision',benefit:'Help the reviewer connect Tom’s ended engagement to the access that may still remain.',input:'Contract-end source, current account state, assignments, activity records, expiry runs and access-review status.',output:'An evidence-backed review brief describing the access gap, confidence limits and proposed cleanup scope.',decision:'The reviewer decides; an authorized operator executes approved changes and checks the result.',moments:['Compare the end date with current account and access state.','Identify possible gaps in workflow scope or execution.','Draft a cleanup recommendation with approval and verification steps.']},
 kwame:{title:'Make offboarding evidence easier to review',benefit:'Help the operations team assemble a traceable account of Kwame’s departure and identify missing proof.',input:'Departure source, workflow history, directory audit events, remaining assignments and application/session evidence.',output:'A timestamped evidence timeline with confirmed outcomes, unresolved exceptions and checks still needed.',decision:'The offboarding owner validates the evidence and confirms completion; AI cannot establish removal without records.',moments:['Compare the departure signal with the current account state.','Separate account disablement from session and entitlement removal.','Assemble the evidence timeline and highlight unsupported claims.']}
};
export function aiContent(p,m,index){const a=aiStories[p.id];return `<div class="ai-overview"><div><span class="ai-label">AI ASSISTANCE · ${escape(p.name)}</span><h3>${escape(a.title)}</h3><p>${escape(a.benefit)}</p></div><span class="ai-mode">${p.agent?'Prepared agent case available':'Illustrative opportunity'}</span></div><section class="ai-moment"><span>FOR THIS MOMENT · ${escape(m.short)}</span><strong>${escape(a.moments[index])}</strong></section><div class="ai-stages"><section><b>01 · Read the evidence</b><p>${escape(a.input)}</p></section><section><b>02 · Propose the next step</b><p>${escape(a.output)}</p></section><section><b>03 · Verify and decide</b><p>${escape(a.decision)}</p></section></div><details class="ai-example" open><summary>Example prompt for this use case</summary><blockquote>“For ${escape(p.name)}, focus on ${escape(m.short.toLowerCase())}. ${escape(a.moments[index])} Use only the supplied records, cite the evidence, identify missing information, and separate recommended actions from completed changes.”</blockquote><p>Discussion prompt only. This page does not send tenant data to an AI model or execute actions.</p></details><div class="ai-next">${p.agent?`<a class="primary" href="${AGENTS}/?case=${p.agent}#run" target="_blank" rel="noopener noreferrer">Open prepared ${escape(p.agent)} case ↗</a><span>Inspect its evidence and proposal in the agent application. The case covers this persona’s broader scenario.</span>`:`<div class="note">No prepared live agent case is linked for ${escape(p.name)}. Use this walkthrough to discuss the opportunity and the evidence an implementation would need.</div>`}</div>`;}
